#pragma once

#define ROBOT_FACE_THEME_GIF_CSS \
    R"THEME(.face-gif-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:9px;margin:14px 0}.face-gif-row{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:9px 10px;border:1px solid var(--line);border-radius:11px;background:#091626}.face-gif-row label{min-width:74px;color:#cfdaea;font-size:11px;font-weight:700}.face-gif-row input{max-width:calc(100% - 80px);min-width:0;color:var(--muted);font-size:10px}.face-gif-settings{display:grid;grid-template-columns:repeat(auto-fit,minmax(145px,1fr));gap:10px}.face-gif-settings input[type=color]{height:38px;padding:4px}.face-gif-progress{width:100%;height:12px;margin:8px 0;accent-color:var(--accent)}.face-gif-tools{display:flex;gap:9px;align-items:center;flex-wrap:wrap}.face-gif-tools button{min-width:190px}.face-gif-delete{margin-top:8px;background:#69283b}.face-gif-note{margin:8px 0;color:var(--muted);font-size:11px;line-height:1.6}@media(max-width:520px){.face-gif-grid{grid-template-columns:1fr}.face-gif-tools button{width:100%}})THEME"

#define ROBOT_FACE_THEME_GIF_HTML \
    R"THEME(<article class="card wide"><div class="card-head"><div><h2>Tạo theme biểu cảm động</h2><p>Chọn tên theme và GIF cho các trạng thái. Trình duyệt tự thu nhỏ, giảm màu rồi tải trực tiếp lên microSD.</p></div><span class="tag">GIF · MICROSD</span></div><details class="advanced"><summary>Tạo theme GIF mới · tối đa 17 biểu cảm</summary><div class="advanced-body">)THEME" \
    R"THEME(<div class="face-gif-settings"><div class="field"><label for="faceGifName">Tên theme</label><input id="faceGifName" maxlength="64" placeholder="Ví dụ: Cherry mùa xuân"></div><div class="field"><label for="faceGifId">Mã theme</label><input id="faceGifId" maxlength="32" placeholder="cherry-mua-xuan"></div><div class="field"><label for="faceGifStyle">Kiểu dự phòng khi thiếu GIF</label><select id="faceGifStyle"><option value="rounded">Rounded</option><option value="soft">Soft</option><option value="pixel">Pixel</option><option value="holo">Holo</option><option value="orbital">Orbital</option><option value="plasma">Plasma</option><option value="demon">Demon</option><option value="capybara">Capybara</option><option value="shiba">Shiba</option><option value="mochi">Mochi</option></select></div><div class="field"><label for="faceGifBackground">Màu nền</label><input id="faceGifBackground" type="color" value="#000000"></div><div class="field"><label for="faceGifPrimary">Màu theme dự phòng</label><input id="faceGifPrimary" type="color" value="#0abde3"></div><div class="field"><label for="faceGifAccent">Màu nhấn</label><input id="faceGifAccent" type="color" value="#ff70ae"></div><div class="field"><label for="faceGifTear">Màu chi tiết</label><input id="faceGifTear" type="color" value="#69d9ff"></div></div>)THEME" \
    R"THEME(<p class="face-gif-note">Có thể chọn một hoặc nhiều trạng thái; trạng thái chưa có GIF sẽ dùng gương mặt vẽ sẵn. Mỗi GIF nguồn tối đa 10 MiB/512×512/120 khung; file sau chuẩn hóa tối đa 256 KiB, 160×160 và 10 fps. GIF được xử lý trên máy tính/điện thoại đang mở trang, không gửi lên máy chủ.</p><div id="faceGifInputs" class="face-gif-grid"></div>)THEME" \
    R"THEME(<div class="face-gif-tools"><button id="faceGifInstall" class="primary" onclick="installFaceGifTheme()">Chuẩn hóa và cài vào thẻ nhớ</button><span id="faceGifProgressText" class="hint">Chọn ít nhất một file GIF.</span></div><progress id="faceGifProgress" class="face-gif-progress" value="0" max="100"></progress></div></details><div id="faceGifCreatorStatus" class="statusline" role="status" aria-live="polite"></div></article>)THEME"

#define ROBOT_FACE_THEME_GIF_SCRIPT \
    R"THEME(const faceGifExpressionDefs=[['neutral','Bình thường'],['happy','Vui'],['sad','Buồn'],['angry','Tức giận'],['surprised','Ngạc nhiên'],['sleepy','Buồn ngủ'],['confused','Bối rối'],['listening','Đang nghe'],['laugh','Cười'],['love','Đáng yêu'],['dizzy','Chóng mặt'],['distracted','Mất tập trung'],['devil','Tinh nghịch'],['confident','Tự tin'],['yawn','Ngáp'],['playful','Nháy mắt'],['speaking','Đang nói']];let faceGifIdTouched=false,faceGifBusy=false;)THEME" \
    R"THEME(function buildFaceGifInputs(){const host=$('faceGifInputs');if(!host)return;host.replaceChildren();for(const [key,label] of faceGifExpressionDefs){const row=document.createElement('div');row.className='face-gif-row';const name=document.createElement('label');name.htmlFor='faceGif_'+key;name.textContent=label;const input=document.createElement('input');input.id='faceGif_'+key;input.type='file';input.accept='image/gif,.gif';input.dataset.expression=key;input.setAttribute('aria-label','GIF '+label);row.append(name,input);host.append(row)}})THEME" \
    R"THEME(function faceGifSlug(value){return value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[đĐ]/g,'d').toLowerCase().replace(/[^a-z0-9_-]+/g,'-').replace(/^-+|-+$/g,'').slice(0,32)})THEME" \
    R"THEME($('faceGifName').addEventListener('input',()=>{if(!faceGifIdTouched)$('faceGifId').value=faceGifSlug($('faceGifName').value)});$('faceGifId').addEventListener('input',()=>{faceGifIdTouched=true;$('faceGifId').value=faceGifSlug($('faceGifId').value)});buildFaceGifInputs();)THEME" \
    R"THEME(async function faceStorageApi(params,options={}){const address='/api/storage?'+new URLSearchParams(params);const response=await fetch(address,options);let data={};try{data=await response.json()}catch(_){}if(!response.ok){const error=new Error(data.error||'HTTP '+response.status);error.status=response.status;throw error}if(data.ok===false)throw Error(data.error||'Thao tác microSD thất bại.');return data})THEME" \
    R"THEME(async function faceEnsureDirectory(path){try{await faceStorageApi({op:'mkdir',path})}catch(error){if(error.status!==409)throw error}})THEME" \
    R"THEME(function faceGifWorker(file,background,onProgress){return new Promise((resolve,reject)=>{const worker=new Worker('/api/face_themes/normalizer.js');const id=Math.random().toString(36).slice(2);worker.onmessage=event=>{const data=event.data||{};if(data.id!==id)return;if(data.type==='progress'){onProgress(data.progress);return}worker.terminate();if(data.type==='done')resolve(data);else reject(Error(data.error||'Không chuẩn hóa được GIF.'))};worker.onerror=event=>{worker.terminate();reject(Error(event.message||'Lỗi khi xử lý GIF trong trình duyệt.'))};file.arrayBuffer().then(buffer=>worker.postMessage({id,buffer,background},[buffer])).catch(error=>{worker.terminate();reject(error)})})})THEME" \
    R"THEME(async function faceThemeUpload(path,blob,onProgress){const chunkSize=32768;let offset=0;do{const chunk=blob.slice(offset,offset+chunkSize);await faceStorageApi({op:'upload',path,offset:String(offset),total:String(blob.size)},{method:'POST',headers:{'Content-Type':'application/octet-stream'},body:chunk});offset+=chunk.size;onProgress(offset,blob.size)}while(offset<blob.size)})THEME" \
    R"THEME(async function installFaceGifTheme(){if(faceGifBusy)return;faceGifBusy=true;const button=$('faceGifInstall'),progress=$('faceGifProgress'),status=$('faceGifCreatorStatus'),progressText=$('faceGifProgressText');button.disabled=true;progress.value=0;let currentUpload='';let createdDirectory='';let installed=false;try{const name=$('faceGifName').value.trim();if(!name||new TextEncoder().encode(name).length>64)throw Error('Nhập tên theme dài tối đa 64 byte UTF-8.');let id=faceGifSlug($('faceGifId').value||name);if(!id)throw Error('Mã theme cần có chữ cái hoặc chữ số.');$('faceGifId').value=id;const selected=faceGifExpressionDefs.map(([key])=>({key,file:$('faceGif_'+key).files[0]})).filter(item=>item.file);if(!selected.length)throw Error('Chọn ít nhất một file GIF.');if(selected.some(item=>item.file.size>10*1024*1024||item.file.size===0))throw Error('Mỗi GIF nguồn phải từ 1 byte đến 10 MiB.');if(faceThemeCatalog.filter(theme=>!theme.builtin).length>=16)throw Error('Đã có 16 theme tùy chỉnh. Xóa một theme trước khi cài thêm.');const storage=await faceStorageApi({op:'status'});if(storage.state!=='mounted')throw Error('Hãy kết nối thẻ microSD trước khi cài theme.');let rootListing;try{rootListing=await faceStorageApi({op:'list',path:'/robot/themes'})}catch(error){if(error.status!==404)throw error}if(rootListing&&(rootListing.entries||[]).some(entry=>entry.name===id||entry.name===id+'.json'))throw Error('Mã theme đã có dữ liệu trên thẻ. Hãy đổi mã khác để tránh ghi đè.');const background=$('faceGifBackground').value.toLowerCase();const folder='/robot/themes/'+id;try{await faceStorageApi({op:'list',path:folder});throw Error('Mã theme đã có thư mục trên thẻ. Hãy đổi mã khác để tránh ghi đè.')}catch(error){if(error.status!==404)throw error}await faceEnsureDirectory('/robot');await faceEnsureDirectory('/robot/themes');await faceEnsureDirectory(folder);createdDirectory=folder;const expressions=[];for(let index=0;index<selected.length;index++){const item=selected[index];if((await faceStorageApi({op:'music_player'})).active)throw Error('Đang phát nhạc từ thẻ. Dừng phát rồi cài theme để không tranh chấp microSD.');progressText.textContent='Đang chuẩn hóa '+item.file.name+' ('+(index+1)+'/'+selected.length+')…';const normalized=await faceGifWorker(item.file,background,value=>{progress.value=Math.round((index+value/100)*85/selected.length)});const path=folder+'/'+item.key+'.gif';currentUpload=path;progressText.textContent='Đang tải '+item.key+'.gif · '+normalized.width+'×'+normalized.height+' · '+normalized.frames+' khung';await faceThemeUpload(path,new Blob([normalized.buffer],{type:'application/octet-stream'}),(sent,total)=>{progress.value=Math.round(((index+sent/total)*85)/selected.length)});currentUpload='';expressions.push(item.key)}const manifest={version:2,id,name,style:$('faceGifStyle').value,primary:$('faceGifPrimary').value.toUpperCase(),accent:$('faceGifAccent').value.toUpperCase(),tear:$('faceGifTear').value.toUpperCase(),background:background.toUpperCase(),expressions};progressText.textContent='Đang kiểm tra và đăng ký theme…';await faceThemeAction('install','',JSON.stringify(manifest));installed=true;createdDirectory='';progress.value=100;progressText.textContent='Đã cài '+expressions.length+' biểu cảm vào '+folder;status.textContent='Theme đã sẵn sàng. Chọn theme trong danh sách phía trên để kích hoạt.';status.className='statusline good'}catch(error){if(currentUpload){try{await faceStorageApi({op:'abort_upload',path:currentUpload},{method:'POST'})}catch(_){}}if(createdDirectory&&!installed){try{const state=await json('/api/face_themes');if(!state.busy)await faceStorageApi({op:'delete',path:createdDirectory},{method:'POST'})}catch(_){}}status.textContent=error.message||'Không cài được theme.';status.className='statusline bad';progressText.textContent='Có thể cần dừng phát nhạc hoặc kiểm tra thẻ microSD rồi thử lại.'}finally{faceGifBusy=false;button.disabled=false;await loadFaceThemes().catch(()=>{})}})THEME"
